// Copies the canonical event catalog (integrations/zapier/lib/events.js) to
// nodes/Cord/events.ts. It only runs inside the Cord repository; the public
// repository of the node receives the generated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const { EVENTS } = require('../../zapier/lib/events.js');

const out = `// Generated by scripts/sync-events.mjs from integrations/zapier/lib/events.js. Do not edit by hand.
import type { INodePropertyOptions } from 'n8n-workflow';

export const EVENTS = ${JSON.stringify(EVENTS, null, '\t')};

export const EVENT_KEYS: string[] = EVENTS.map((e) => e.key);

export const EVENT_OPTIONS: INodePropertyOptions[] = EVENTS.map((e) => ({
\tname: \`\${e.category}: \${e.label}\`,
\tvalue: e.key,
}));
`;

const target = new URL('../nodes/Cord/events.ts', import.meta.url);
const current = (() => { try { return readFileSync(target, 'utf8'); } catch { return ''; } })();
if (current === out) console.log('nodes/Cord/events.ts is up to date');
else { writeFileSync(target, out); console.log(`nodes/Cord/events.ts updated (${EVENTS.length} events)`); }
